def main():
    with open(PATH, "r", encoding="utf-8") as f:
        state = json.load(f)

    # Push prior last_decision to history (only if different)
    prior = state.get("last_decision")
    if prior and prior.get("ist_time") != "2026-08-31 11:10:00":
        history = state.get("history", [])
        if not history or history[0].get("ist_time") != prior.get("ist_time"):
            history.insert(0, prior)
            if len(history) > 50:
                history = history[:50]
            state["history"] = history

    # Replace last_decision
    state["last_decision"] = new_decision
    state["today_date"] = "2026-08-31"
    state["call_count_today"] = state.get("call_count_today", 0) + 1
    state["timestamp"] = "2026-08-31T11:10:00Z"

    with open(PATH, "w", encoding="utf-8") as f:
        json.dump(state, f, indent=2, ensure_ascii=False)

    print(f"OK updated call_count={state['call_count_today']} history_size={len(state.get('history', []))}")


